examples.code:
#include <map>
#include <cassert>
#include <iostream>

int main() {
    std::multimap<int, int> values{{1, 10}, {3, 30}};
    values.insert({2, 20});
    values.emplace_hint(values.end(), 4, 40);
    assert(values.count(2) == 1);
    auto first = values.lower_bound(2);
    auto last = values.upper_bound(2);
    assert(first->first == 2);
    assert(last->first == 3);
    auto allocator = values.get_allocator();
    (void)allocator;
    assert(values.value_comp()(*values.begin(), *first));
    // The container releases its storage automatically at the end of this scope.
    std::cout << "Checks passed\n";
}
